<?php
require_once dirname(__DIR__).'/tests/integration/TestBootstrap.php';$db=DagrilIntegrationTest::boot();
require_once dirname(__DIR__).'/app/models/Agriculture.php';require_once dirname(__DIR__).'/app/models/WeighbridgeTransport.php';require_once dirname(__DIR__).'/app/models/Weighing.php';
$mut=(int)DagrilIntegrationTest::scalar("SELECT id FROM sites WHERE code='FARM-MUT'");$siloSite=(int)DagrilIntegrationTest::scalar("SELECT id FROM sites WHERE code='SILO'");$season=(int)DagrilIntegrationTest::scalar('SELECT id FROM agricultural_seasons LIMIT 1');$variety=DagrilIntegrationTest::row('SELECT v.id,v.product_id FROM agricultural_varieties v LIMIT 1');if(!$mut||!$siloSite||!$season||!$variety)throw new RuntimeException('Référentiels agricoles incomplets.');
$creator=DagrilIntegrationTest::loginRole('administrateur',$mut);$suffix=strtoupper(bin2hex(random_bytes(4)));$ag=new Agriculture();
$campaign=$ag->createCampaign(['season_id'=>$season,'code'=>'IT-C-'.$suffix,'name'=>'Intégration MUTALA vers silo','start_date'=>date('Y-m-d'),'end_date'=>date('Y-m-d',strtotime('+3 months'))],$creator);
$plot=$ag->createPlot(['code'=>'IT-P-'.$suffix,'name'=>'Parcelle intégration','total_area_ha'=>5]);$cp=$ag->planPlot(['campaign_id'=>$campaign,'plot_id'=>$plot,'variety_id'=>$variety['id'],'planned_area_ha'=>5,'actual_area_ha'=>5,'target_tons_per_ha'=>2]);
$harvest=$ag->createHarvest(['campaign_plot_id'=>$cp,'harvested_at'=>date('Y-m-d H:i:s'),'gross_weight_kg'=>11000,'tare_weight_kg'=>500,'drying_loss_kg'=>500,'moisture_before'=>17,'moisture_after'=>13,'drying_started_at'=>date('Y-m-d H:i:s'),'drying_ended_at'=>date('Y-m-d H:i:s')],$creator);
$validator=DagrilIntegrationTest::loginRole('direction',$mut);$stock=$ag->validateHarvest($harvest,$validator);DagrilIntegrationTest::check((float)DagrilIntegrationTest::scalar('SELECT physical_quantity_kg FROM agricultural_stocks WHERE id=?',[$stock])===10000.0,'Récolte validée crée 10 000 kg de stock MUTALA');
$creator=DagrilIntegrationTest::loginRole('administrateur',$mut);$bt=$ag->createTransport(['stock_id'=>$stock,'quantity_kg'=>10000,'truck_plate'=>'IT-'.$suffix,'driver_name'=>'Chauffeur MUTALA','route_description'=>'MUTALA - SILO'],$creator);$validator=DagrilIntegrationTest::loginRole('direction',$mut);$ag->approveTransport($bt,$validator);
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar('SELECT COUNT(*) FROM weighbridge_transports WHERE agricultural_transport_id=?',[$bt])===0,'BT approuvé non visible au pont-bascule avant expédition');
$transport=$ag->dispatchTransport($bt,$validator);
$bridge=DagrilIntegrationTest::row('SELECT * FROM weighbridge_transports WHERE id=?',[$transport]);
DagrilIntegrationTest::check((int)$bridge['agricultural_transport_id']===(int)$bt&&(int)$bridge['site_id']===$siloSite,'Transport créé automatiquement et rattaché au site de réception SILO');
DagrilIntegrationTest::check((int)$bridge['origin_site_id']===$mut&&(int)$bridge['product_id']===(int)$variety['product_id']&&(float)$bridge['shipped_quantity_kg']===10000.0,'Origine, produit et quantité repris du BT agricole');
$official=DagrilIntegrationTest::scalar("SELECT d.document_number FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BT' AND d.entity_type='agricultural_transports' AND d.entity_id=?",[$bt]);
DagrilIntegrationTest::check($bridge['transport_reference']===$official,'Référence officielle agricole conservée');
DagrilIntegrationTest::expectException(function()use($ag,$bt,$validator){$ag->dispatchTransport($bt,$validator);},'Double expédition refusée');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar('SELECT COUNT(*) FROM weighbridge_transports WHERE agricultural_transport_id=?',[$bt])===1,'Un seul transport pour le BT agricole');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BT' AND d.entity_type='agricultural_transports' AND d.entity_id=?",[$bt])===1,'BT agricole officiel créé');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM agricultural_stock_movements WHERE stock_id=? AND movement_type='transport_out'",[$stock])===1,'Sortie agricole journalisée une seule fois');
$creator=DagrilIntegrationTest::loginRole('administrateur',$siloSite);$db->prepare("INSERT INTO silos(site_id,name,code,product_id,capacity_kg,current_stock_kg,status) VALUES(?,?,?,?,20000,0,'active')")->execute([$siloSite,'Silo intégration','IT-S-'.$suffix,$variety['product_id']]);$silo=(int)$db->lastInsertId();$available=(new Weighing())->availableTransports();
DagrilIntegrationTest::check(in_array((int)$transport,array_map('intval',array_column($available,'id')),true),'BT agricole proposé dans le formulaire de pesée d’entrée');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM documents WHERE entity_type='weighbridge_transports' AND entity_id=?",[$transport])===0,'Pas de second document BT créé');

$weighing=(new Weighing())->createEntry(['transport_id'=>$transport,'poids_brut'=>12000],$creator);DagrilIntegrationTest::check((float)DagrilIntegrationTest::scalar('SELECT current_stock_kg FROM silos WHERE id=?',[$silo])===0.0,'Pesée brute sans entrée silo');
$validator=DagrilIntegrationTest::loginRole('direction',$siloSite);(new Weighing())->validateExit($weighing,['poids_tare'=>2000,'silo_id'=>$silo,'humidity_percent'=>13,'impurities_percent'=>1,'weight_tolerance_percent'=>2,'max_humidity_percent'=>14,'max_impurities_percent'=>2,'quality_notes'=>'Conforme','decision'=>'accept'],$validator);
DagrilIntegrationTest::check((float)DagrilIntegrationTest::scalar('SELECT current_stock_kg FROM silos WHERE id=?',[$silo])===10000.0,'Récolte MUTALA reçue intégralement au silo');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM silo_movements WHERE weighing_id=? AND movement_type='in' AND status='validated'",[$weighing])===1,'Mouvement d’entrée silo validé');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BRS' AND d.entity_type='weighings' AND d.entity_id=?",[$weighing])===1,'BRS créé dans la transaction de validation');
DagrilIntegrationTest::check((int)DagrilIntegrationTest::scalar("SELECT COUNT(*) FROM activity_logs WHERE entity_id IN (?,?) AND module IN('agriculture','pont-bascule')",[$bt,$weighing])>0,'Chaîne agricole auditée');
DagrilIntegrationTest::expectException(function()use($weighing,$validator,$silo){(new Weighing())->validateExit($weighing,['poids_tare'=>2000,'silo_id'=>$silo,'humidity_percent'=>13,'impurities_percent'=>1,'weight_tolerance_percent'=>2,'max_humidity_percent'=>14,'max_impurities_percent'=>2,'quality_notes'=>'','decision'=>'accept'],$validator);},'Double validation de la pesée agricole refusée');
DagrilIntegrationTest::check(!in_array((int)$transport,array_map('intval',array_column((new Weighing())->availableTransports(),'id')),true),'Transport reçu retiré de la liste des entrées disponibles');
DagrilIntegrationTest::check((new Weighing())->findDetailed($weighing)['bt_number']===$official,'Ticket de pesée affiche le BT agricole original');
DagrilIntegrationTest::finish();
